import os
import requests

BASE_URL = "https://api.spotify.com/v1"
headers = {"Authorization": f"Bearer {os.environ['SPOTIFY_ACCESS_TOKEN']}"}

recent = requests.get(
    f"{BASE_URL}/me/player/recently-played",
    headers=headers,
    params={"limit": 1},
)
recent.raise_for_status()
items = recent.json().get("items", [])

if items:
    artist_ids = [
        artist["id"]
        for artist in items[0]["track"].get("artists", [])
        if artist.get("id")
    ]
    if artist_ids:
        response = requests.put(
            f"{BASE_URL}/me/following",
            headers=headers,
            params={"type": "artist", "ids": ",".join(artist_ids)},
        )
        response.raise_for_status()

