import requests

BASE_URL = "https://api.spotify.com/v1"
TOKEN = "YOUR_ACCESS_TOKEN"
HEADERS = {"Authorization": f"Bearer {TOKEN}"}

response = requests.get(
    f"{BASE_URL}/me/playlists",
    headers=HEADERS,
    params={"limit": 50},
)
response.raise_for_status()

playlist = next(
    (item for item in response.json().get("items", []) if item.get("name") == "My R&B"),
    None,
)
if playlist is None:
    raise ValueError("Playlist 'My R&B' was not found.")

playlist_id = playlist["id"]
artist_ids = set()
url = f"{BASE_URL}/playlists/{playlist_id}/tracks"
params = {"limit": 100}

while url:
    response = requests.get(url, headers=HEADERS, params=params)
    response.raise_for_status()
    data = response.json()

    for item in data.get("items", []):
        track = item.get("track") or {}
        for artist in track.get("artists", []):
            if artist.get("id"):
                artist_ids.add(artist["id"])

    url = data.get("next")
    params = None

if artist_ids:
    response = requests.put(
        f"{BASE_URL}/me/following",
        headers=HEADERS,
        params={"type": "artist", "ids": ",".join(sorted(artist_ids))},
    )
    response.raise_for_status()

